/* ===== Arcanes · Histoire de l'astrologie, dix chapitres =====
   Les clefs "@h0" à "@h8" désignent les images déjà embarquées dans astro-img.js.
   Autres images : Wellcome Collection (domaine public ou CC BY 4.0), Art Institute of Chicago (CC0). */
window.ASTRO_HISTOIRE = [
{ id:"a1", n:"I", court:"Babylone", t:"Babylone : le ciel est une écriture", per:"IIe millénaire – IVe siècle av. J.-C.",
  lieux:[["Babylone","Irak"],["Ninive","Mossoul, Irak"],["Ourouk","sud de l'Irak"]],
  hero:["@h0","Un « journal astronomique » babylonien de 331-330 av. J.-C. La même tablette note la position des planètes, le prix de l'orge et la mort d'Alexandre. British Museum."],
  lead:"L'astrologie naît en Mésopotamie, entre le Tigre et l'Euphrate. Elle n'y est pas une science des caractères : c'est un service de renseignement. Les dieux écrivent leurs intentions dans le ciel, et des scribes sont payés pour les lire avant qu'il ne soit trop tard.",
  blocs:[
   {h:"Des présages pour le roi",
    p:["Les Babyloniens appellent les étoiles « l'écriture du ciel ». Chaque phénomène est un signe, comme le foie d'un mouton sacrifié ou le vol d'un oiseau. À la fin du IIe millénaire, on réunit ces signes dans un recueil qui porte le nom de ses premiers mots, <b>Enuma Anu Enlil</b>, « Quand Anou et Enlil » : soixante-dix tablettes, environ sept mille présages. Leur forme est toujours la même. Si la Lune est entourée d'un halo et que Jupiter s'y tient, le roi sera assiégé. Si Vénus disparaît à l'ouest tel mois, il y aura des pluies.",
       "Ces présages concernent le pays, la récolte, la guerre, la vie du roi. Jamais un particulier. Et ils ne sont pas une fatalité : un signe est un avertissement, que des rites permettent de détourner. Quand une éclipse menace le souverain, on installe sur le trône un <b>roi de substitution</b>, un homme du peuple qui attire sur lui le malheur annoncé, pendant que le vrai roi se cache sous le nom de « fermier ».",
       "Nous connaissons ce travail de l'intérieur. La bibliothèque de <b>Ninive</b> a conservé des centaines de lettres envoyées aux rois assyriens Assarhaddon et Assurbanipal, au VIIe siècle avant notre ère, par une dizaine d'équipes d'observateurs réparties dans l'empire. Ils signalent ce qu'ils ont vu, citent le présage, rassurent ou alertent, et se jalousent entre eux."]},
   {h:"De l'observation au calcul",
    p:["Pour lire des signes, il faut savoir ce qui est normal. Les scribes dressent des listes d'étoiles, dont la plus célèbre, <b>MUL.APIN</b>, fixe vers l'an 1000 avant notre ère les constellations que la Lune traverse. À Babylone, à partir de 652 avant notre ère au moins, des observateurs notent chaque nuit la position de la Lune et des planètes, le temps qu'il fait, le niveau du fleuve et les prix du marché. Ces <b>journaux astronomiques</b> sont tenus pendant six siècles : c'est la plus longue série d'observations de l'histoire.",
       "De ces archives sortent des régularités. Les Babyloniens apprennent à prévoir les éclipses et les retours des planètes par de simples suites de nombres. Vers le Ve siècle, pour repérer les astres, ils découpent la route du Soleil en <b>douze signes égaux</b> de trente degrés, nommés d'après les constellations voisines. Le zodiaque est né, comme un outil de mesure."]},
   {h:"Le premier horoscope",
    p:["Quand la Mésopotamie passe sous domination perse, la cour de Babylone disparaît, et avec elle le principal client. Les savants se tournent vers les particuliers. La plus ancienne tablette de naissance connue date de <b>410 avant notre ère</b> : elle donne, pour le jour où un enfant est né, le signe où se trouvaient la Lune et chaque planète. On en connaît une trentaine, trouvées à Babylone et à Ourouk. Elles sont brèves, presque sans commentaire.",
       "L'idée est neuve et elle ira loin : le ciel d'un instant dit quelque chose d'une personne. Mais ces tablettes n'ont ni Ascendant ni maisons. Il leur manque l'heure."]}
  ],
  gens:[
   {n:"Les scribes de l'Enuma Anu Enlil", role:"Observateurs et devins du roi",
    t:"On les appelle <i>tupshar Enuma Anu Enlil</i>, « scribes du Quand Anou et Enlil ». Ils forment des familles, se transmettent le métier de père en fils, et travaillent dans les temples. Quelques noms nous sont parvenus, comme Balasî, précepteur du prince Assurbanipal."}],
  qr:[
   ["Pourquoi douze signes ?","Parce que l'année compte environ douze lunaisons. Le Soleil parcourt donc à peu près un douzième de sa route par mois. Les Babyloniens, qui comptaient en base soixante, ont donné trente degrés à chaque part."],
   ["Les Babyloniens croyaient-ils que les planètes agissent sur nous ?","Non. Pour eux, les astres ne causent rien : ils annoncent, comme un message. L'idée d'une influence physique des planètes viendra des Grecs."],
   ["Qui sont les « Chaldéens » ?","La Chaldée est le sud de la Babylonie. Pour les Grecs et les Romains, le mot a fini par désigner tout astrologue, quelle que soit son origine."],
   ["Les planètes portaient-elles déjà leurs noms ?","Elles portaient ceux des dieux de Babylone : Mardouk pour Jupiter, Ishtar pour Vénus, Nergal pour Mars, Nabou pour Mercure, Ninourta pour Saturne. Les Grecs ont traduit par leurs propres dieux, puis les Romains par les leurs."]],
  mots:[["présage","Un signe envoyé par les dieux, que l'on peut encore détourner."],["écliptique","La route apparente du Soleil dans le ciel au cours de l'année."],["zodiaque","La bande du ciel, de part et d'autre de l'écliptique, découpée en douze signes."]],
  globe:[["babylone","Babylone"],["r_astro","La route de l'astrologie"]],
  suite:"Ce savoir va voyager vers l'ouest dans les bagages d'un prêtre, et y rencontrer la géométrie." },

{ id:"a2", n:"II", court:"Alexandrie", t:"Alexandrie : l'invention de l'horoscope", per:"IIIe – Ier siècle av. J.-C.",
  lieux:[["Alexandrie","Égypte"],["Cos","île grecque"],["Dendérah","Haute-Égypte"]],
  hero:["astro/img/ah_dendera.webp","Le zodiaque circulaire du temple de Dendérah, vers 50 av. J.-C., ici dans une gravure coloriée d'après Vivant Denon. On y voit se mêler les douze signes venus de Babylone et les figures du ciel égyptien. L'original est au Louvre. Wellcome Collection, domaine public."],
  lead:"L'astrologie que nous pratiquons encore, avec son Ascendant, ses maisons et ses aspects, n'est ni babylonienne ni tout à fait grecque. Elle a été assemblée en Égypte, en quelques générations, par des gens qui écrivaient en grec et mêlaient trois héritages.",
  blocs:[
   {h:"Trois héritages",
    p:["Après les conquêtes d'Alexandre, mort à Babylone en 323 avant notre ère, les savoirs circulent d'un bout à l'autre de son empire. Vers 280, un prêtre babylonien, <b>Bérose</b>, s'installe sur l'île de <b>Cos</b> et y enseigne en grec la science de son pays. Les Grecs découvrent le zodiaque, les périodes des planètes et l'idée de l'horoscope de naissance.",
       "L'Égypte apporte autre chose. Depuis le IIIe millénaire, ses prêtres comptent les heures de la nuit grâce à trente-six étoiles qui se lèvent tour à tour, de dix jours en dix jours : les <b>décans</b>. On les peint à l'intérieur des couvercles de cercueils. Ils deviendront des divisions de dix degrés à l'intérieur de chaque signe.",
       "Les Grecs, enfin, fournissent la géométrie de la sphère et une physique. Le monde d'Aristote est fait de quatre éléments, feu, terre, air et eau, et de quatre qualités, le chaud, le froid, le sec et l'humide. On range les signes par éléments, on donne aux planètes un tempérament, et l'on mesure les angles qui les séparent : ce sont les <b>aspects</b>."]},
   {h:"L'heure entre en scène",
    p:["La grande nouveauté tient en un mot grec, <b>hôroskopos</b>, « celui qui observe l'heure ». C'est le point du zodiaque qui se lève à l'horizon est à l'instant de la naissance. Comme la Terre tourne, il change de signe toutes les deux heures environ : deux enfants nés le même jour n'ont plus le même ciel. Nous l'appelons l'Ascendant.",
       "À partir de lui, on divise le ciel en douze <b>lieux</b>, nos maisons, qui correspondent chacun à un domaine de la vie : le corps, les biens, les frères, les parents, les enfants, la maladie, le mariage, la mort, les voyages, le métier, les amis, les épreuves. Une planète ne signifie plus seulement par le signe où elle est, mais par le lieu qu'elle occupe et par ceux qu'elle gouverne.",
       "Tout cela apparaît en même temps, au IIe ou au Ier siècle avant notre ère, comme un système déjà complet. Les premiers manuels sont perdus. Ils circulaient sous des noms prestigieux : <b>Hermès Trismégiste</b>, et surtout le pharaon <b>Néchepso</b> et le prêtre <b>Pétosiris</b>, que tous les astrologues grecs citeront comme leurs fondateurs."]},
   {h:"L'ordre des planètes et les jours de la semaine",
    p:["Les astronomes grecs rangent les sept astres mobiles du plus lent au plus rapide : Saturne, Jupiter, Mars, le Soleil, Vénus, Mercure, la Lune. C'est l'ordre dit chaldéen. Les astrologues attribuent à chaque heure du jour et de la nuit une planète, en suivant cet ordre sans s'arrêter. La planète de la première heure donne son nom à la journée. En comptant vingt-quatre heures, on tombe chaque matin trois rangs plus loin : après le jour de Saturne vient celui du Soleil, puis celui de la Lune, de Mars, de Mercure, de Jupiter, de Vénus. Notre <b>semaine</b> vient de là, et tu la prononces encore : lundi, mardi, mercredi, jeudi, vendredi."]}
  ],
  gens:[
   {n:"Bérose", d:"vers 290 av. J.-C.", role:"Prêtre de Bêl à Babylone, professeur à Cos",
    t:"Il écrit en grec une histoire de la Babylonie dédiée au roi Antiochos Ier. L'architecte romain Vitruve le cite comme le premier à avoir ouvert une école d'astrologie en pays grec. Les Athéniens lui auraient élevé une statue à la langue dorée."},
   {n:"Néchepso et Pétosiris", d:"IIe siècle av. J.-C. pour le texte", role:"Auteurs supposés du premier grand traité",
    t:"Un roi et un prêtre égyptiens à qui l'on attribuait une révélation reçue des dieux. Le livre est perdu, mais les fragments cités par Vettius Valens montrent qu'il contenait déjà les lieux, les parts et les calculs de durée de vie."}],
  qr:[
   ["Pourquoi l'Égypte ?","Parce qu'Alexandrie, fondée en 331 avant notre ère, est alors la capitale savante du monde grec, avec sa bibliothèque et son Musée, et que les prêtres égyptiens ont une réputation d'antique sagesse. On y trouve à la fois les mathématiciens et les temples."],
   ["Le zodiaque de Dendérah est-il très ancien ?","Non. Quand les savants de Bonaparte le découvrent en 1799, on le croit vieux de milliers d'années. Champollion et les astronomes ont montré qu'il date de la fin de l'époque grecque, vers 50 avant notre ère."],
   ["L'astrologie vient-elle donc d'Égypte ?","Sa forme, oui. Ses matériaux viennent d'ailleurs : le zodiaque et l'horoscope de Babylone, la géométrie et la physique de Grèce. Les Anciens préféraient dire qu'elle était égyptienne, parce que cela faisait plus vénérable."]],
  mots:[["hôroskopos","Le degré qui se lève à l'est à la naissance : l'Ascendant."],["décan","Un tiers de signe, soit dix degrés."],["aspect","L'angle qui sépare deux planètes vues de la Terre."]],
  globe:[["egypte","L'Égypte ancienne"],["hermetisme","L'hermétisme"]],
  suite:"Ce système tout neuf va trouver son plus grand marché : Rome." },

{ id:"a3", n:"III", court:"Rome", t:"Rome : les empereurs et les grands manuels", per:"Ier siècle av. J.-C. – Ve siècle",
  lieux:[["Rome","Italie"],["Alexandrie","Égypte"],["Antioche","Antakya, Turquie"],["Hippone","Annaba, Algérie"]],
  hero:["@h2","L'Atlas Farnèse, copie romaine du IIe siècle : le plus ancien globe céleste conservé, avec ses constellations en relief. Musée archéologique de Naples. Photo Yair Haklai, CC BY-SA 4.0."],
  lead:"À Rome, l'astrologie est partout : au palais, où elle sert à gouverner, et sur le Champ de Mars, où l'on consulte pour quelques pièces. C'est aussi sous l'Empire que sont écrits les livres dont toute la tradition dépend, et que se formulent contre elle des objections qui n'ont pas vieilli.",
  blocs:[
   {h:"Une affaire d'État",
    p:["Les premiers astrologues arrivent à Rome avec les esclaves et les marchands d'Orient. Dès 139 avant notre ère, un magistrat expulse les « Chaldéens » de la ville. La mesure sera répétée une dizaine de fois en deux siècles, ce qui montre qu'elle ne servait à rien.",
       "Les empereurs s'en méfient parce qu'ils y croient. <b>Auguste</b> fait publier son thème et frappe des monnaies au signe du Capricorne ; puis, en l'an 11, il interdit de consulter sur la date d'une mort, et d'abord sur la sienne. <b>Tibère</b>, retiré à Capri, garde auprès de lui le savant <b>Thrasylle</b>, qui lit pour lui les thèmes de ses rivaux. Connaître l'horoscope de l'empereur devient un crime ; avoir soi-même un « thème impérial » peut coûter la vie."]},
   {h:"Les livres fondateurs",
    fig:["@h1","Claude Ptolémée, gravure. Les artistes l'ont longtemps coiffé d'une couronne, en le confondant avec les rois Ptolémée d'Égypte. Wellcome Collection, CC BY 4.0."],
    p:["Le plus ancien traité complet qui nous reste est un poème latin, les <i>Astronomiques</i> de <b>Manilius</b>, écrit sous Auguste et Tibère. Au Ier siècle, <b>Dorothée de Sidon</b> compose en vers grecs un manuel pratique, que nous ne lisons plus qu'à travers une traduction arabe.",
       "Vers 150, à Alexandrie, <b>Claude Ptolémée</b>, l'auteur du grand traité d'astronomie qu'on appellera l'<i>Almageste</i>, lui donne un second volet, le <b>Tétrabible</b>, « les quatre livres ». Il y cherche des causes. Le Soleil chauffe, la Lune humidifie, cela se constate ; les autres planètes agissent de même, chacune selon son tempérament, sur l'air qui nous entoure, et à travers lui sur les corps et les caractères. L'astrologie devient une branche de la physique. Ptolémée ajoute qu'elle est conjecturale, comme la médecine : elle peut se tromper, cela ne prouve pas qu'elle soit vaine. Ce livre fera autorité pendant quinze siècles.",
       "Son contemporain <b>Vettius Valens</b>, d'Antioche, est tout le contraire d'un théoricien. Ses <i>Anthologies</i> sont le carnet d'un praticien qui a couru l'Égypte pour trouver des maîtres : plus de cent thèmes réels, des techniques pour dater les événements d'une vie, et des confidences. Vers 335, enfin, le Sicilien <b>Firmicus Maternus</b> rédige en latin la <i>Mathesis</i>, la somme la plus complète de l'Antiquité."]},
   {h:"Les signes ne sont plus les constellations",
    p:["Vers 130 avant notre ère, l'astronome <b>Hipparque</b> avait remarqué que le point du ciel où se trouve le Soleil à l'équinoxe de printemps recule lentement par rapport aux étoiles : c'est la <b>précession</b>, un tour complet en vingt-six mille ans environ. Ptolémée en tire une décision capitale. Il attache le zodiaque aux saisons et non aux étoiles : le Bélier commence, par définition, à l'équinoxe de printemps. C'est le zodiaque <b>tropical</b>, celui de toute l'astrologie occidentale.",
       "Depuis, les signes et les constellations du même nom se sont décalés d'environ vingt-quatre degrés, presque un signe entier. Quand on dit aujourd'hui que le Soleil est en Bélier, il se trouve devant les étoiles des Poissons. Ce n'est pas une erreur des astrologues, c'est une convention ancienne. L'astrologie indienne a fait l'autre choix."]},
   {h:"Les objections",
    p:["Elles sont toutes formulées dès l'Antiquité. Le philosophe <b>Carnéade</b>, au IIe siècle avant notre ère, puis <b>Cicéron</b> dans son traité <i>De la divination</i>, demandent : comment deux jumeaux, nés sous le même ciel, peuvent-ils avoir des vies différentes ? Et les milliers de soldats tombés le même jour à la bataille de Cannes avaient-ils tous le même horoscope ? Les astrologues répondent que quelques minutes suffisent à changer l'Ascendant, et que le destin d'une armée l'emporte sur celui d'un homme.",
       "Les chrétiens ajoutent un argument moral : si les astres décident, où est la liberté, et que vaut le péché ? <b>Augustin</b>, qui a longtemps consulté les astrologues, raconte dans ses <i>Confessions</i> ce qui l'a détrompé : un ami lui apprit que son père avait noté au même instant la naissance de son fils et celle de l'enfant d'une esclave. L'un devint riche, l'autre resta esclave. Dans l'Occident latin, où l'on ne sait bientôt plus le grec ni les mathématiques, l'astrologie savante s'éteint pour six siècles."]}
  ],
  gens:[
   {n:"Claude Ptolémée", d:"vers 100 – vers 170", img:"astro/img/ah_ptolemee2.webp", cap:"Ptolémée, gravure sur bois de Tobias Stimmer, 1587. Wellcome Collection.", role:"Astronome, géographe et astrologue d'Alexandrie",
    t:"On ne sait presque rien de sa vie. Il a fixé pour quinze siècles l'image d'un monde centré sur la Terre. Son astrologie est sobre : il écarte les lieux et beaucoup de recettes pour ne garder que ce qu'il croit pouvoir expliquer."},
   {n:"Vettius Valens", d:"120 – vers 175", role:"Astrologue praticien, né à Antioche",
    t:"Il se plaint des maîtres avares et des élèves ingrats, et fait jurer le secret à ses lecteurs. Grâce à lui, on connaît les techniques réelles des astrologues grecs : profections annuelles, parts, périodes planétaires."},
   {n:"Thrasylle", d:"mort en 36", role:"Savant alexandrin, astrologue de Tibère",
    t:"Également éditeur des dialogues de Platon. Selon Tacite, Tibère éprouvait ses astrologues en les menant sur une falaise ; Thrasylle se sauva en annonçant qu'un grand danger le menaçait à l'instant même."}],
  qr:[
   ["Mon signe est-il faux à cause du décalage ?","Non, il repose sur une autre définition. En astrologie occidentale, ton signe dit à quel moment de l'année tu es né, pas devant quelles étoiles se tenait le Soleil. Les deux zodiaques coïncidaient à peu près à l'époque de Ptolémée."],
   ["Et le « treizième signe » ?","Le Soleil traverse bien une treizième constellation, le Serpentaire. Mais les signes sont douze parts égales du cercle, une mesure et non un dessin d'étoiles. Les Babyloniens le savaient déjà."],
   ["L'Église a-t-elle interdit l'astrologie ?","Elle a condamné l'astrologie qui prétend prédire les actes humains, parce qu'elle nie la liberté. Elle a généralement toléré celle qui s'en tient au temps qu'il fait, aux récoltes et à la médecine."]],
  mots:[["Tétrabible","Le traité d'astrologie de Ptolémée, en quatre livres."],["précession","Le lent recul du point de l'équinoxe par rapport aux étoiles."],["zodiaque tropical","Celui qui commence à l'équinoxe de printemps, quelle que soit la position des étoiles."]],
  suite:"Pendant que l'Occident oublie, les livres grecs partent vers l'est." },

{ id:"a4", n:"IV", court:"Perse, Inde, Chine", t:"Vers l'est : la Perse, l'Inde et la Chine", per:"IIe – VIIIe siècle",
  lieux:[["Ctésiphon","près de Bagdad, Irak"],["Ujjain","Inde"],["Chang'an","Xi'an, Chine"],["Lhassa","Tibet"]],
  hero:["astro/img/ah_inde.webp","Un astrologue indien à son travail, aquarelle, vers 1825. Assis devant ses feuilles de palmier, il calcule le thème d'un client. Wellcome Collection, domaine public."],
  lead:"L'astrologie grecque n'a pas attendu les Arabes pour quitter la Méditerranée. Elle a suivi les routes du commerce jusqu'en Inde, où elle vit encore, et elle a croisé en chemin une autre grande tradition, née en Chine sans rien lui devoir.",
  blocs:[
   {h:"L'Inde : le jyotisha",
    fig:["astro/img/ah_indezod.webp","Le zodiaque indien, gravure du XIXe siècle : les douze signes reçus des Grecs, et les vingt-sept demeures de la Lune. Wellcome Collection, domaine public."],
    p:["Les textes védiques connaissaient déjà les <b>nakshatra</b>, vingt-sept ou vingt-huit groupes d'étoiles qui marquent les étapes de la Lune. Dans les premiers siècles de notre ère, par les ports de la côte ouest où abordent les navires d'Alexandrie, arrive l'horoscope. Un traité sanskrit s'intitule sans détour <b>Yavanajataka</b>, « l'horoscopie des Grecs ». Les mots techniques trahissent l'emprunt : <i>hora</i> pour l'heure, <i>kendra</i> pour le centre.",
       "Au VIe siècle, à <b>Ujjain</b>, <b>Varahamihira</b> donne à cette science, le <i>jyotisha</i>, sa forme classique. L'Inde y ajoute beaucoup : des périodes planétaires qui découpent toute la vie, des thèmes dérivés, deux « planètes d'ombre », Rahu et Ketu, qui sont les nœuds de la Lune. Surtout, elle garde un zodiaque <b>sidéral</b>, attaché aux étoiles. C'est pourquoi ton signe n'est souvent pas le même dans un thème indien.",
       "Cette astrologie n'a jamais été interrompue. Elle sert encore à choisir la date d'un mariage ou le nom d'un enfant, et elle s'enseigne dans des universités indiennes."]},
   {h:"La Perse : l'histoire au rythme des planètes",
    p:["Sous les rois sassanides, à partir du IIIe siècle, on traduit en moyen-perse Dorothée et Vettius Valens, et l'on y mêle des apports indiens. Les astrologues perses mettent au point une idée promise à un grand avenir : l'histoire des empires et des religions suit le rythme des <b>conjonctions de Jupiter et de Saturne</b>, qui se rencontrent tous les vingt ans et changent de famille de signes tous les deux siècles environ. Les Arabes hériteront de ces livres, et de ces savants."]},
   {h:"La Chine : une autre astrologie",
    fig:["astro/img/ah_tibet.webp","Un diagramme cosmologique tibétain de protection : au centre, la tortue cosmique, les neuf carrés magiques et les douze animaux. Le Tibet a mêlé les traditions de l'Inde et de la Chine. Wellcome Collection, domaine public."],
    p:["La Chine a regardé le ciel aussi longtemps que Babylone, et pour la même raison : y lire des avertissements adressés à l'empereur, qui règne par « mandat du Ciel ». Mais son système est différent. Le ciel y est centré sur le pôle, non sur la route du Soleil, et divisé en vingt-huit <b>loges lunaires</b>. Le temps se compte par cycles de soixante, combinant dix « troncs » et douze « rameaux », auxquels on associe douze <b>animaux</b>, du Rat au Cochon, et cinq agents : bois, feu, terre, métal, eau.",
       "L'astrologie chinoise des personnes part de l'année, du mois, du jour et de l'heure de naissance, sans calcul de planètes. Les douze signes grecs sont bien arrivés en Chine, avec le bouddhisme, sous la dynastie Tang, mais ils n'y ont pas pris racine."]}
  ],
  gens:[
   {n:"Varahamihira", d:"VIe siècle", role:"Astronome et astrologue d'Ujjain",
    t:"Auteur d'une somme d'astronomie qui compare cinq systèmes, dont deux grecs, et du <i>Brihat Jataka</i>, resté le manuel de base de l'astrologie indienne. Il écrit que les Grecs, bien qu'étrangers, méritent d'être honorés comme des sages pour cette science."}],
  qr:[
   ["Astrologie « védique » et occidentale : la même chose ?","Elles ont un tronc commun, l'horoscope grec, et douze signes de même nom. Mais le zodiaque indien est décalé d'environ vingt-quatre degrés, et les techniques de prévision sont différentes."],
   ["Les animaux chinois sont-ils des signes du zodiaque ?","Pas au sens occidental. Ils ne correspondent pas à des portions du ciel mais à des années, des mois, des jours et des heures. Les deux systèmes n'ont pas d'origine commune."]],
  mots:[["jyotisha","« Science des lumières » : l'astronomie-astrologie de l'Inde."],["nakshatra","Une des vingt-sept demeures de la Lune."],["zodiaque sidéral","Celui qui reste attaché aux étoiles."]],
  globe:[["veda","Le monde védique"],["tao","Le taoïsme"],["yijing","Le Yi Jing"]],
  suite:"Tous ces fils, grec, perse et indien, vont se renouer dans une ville qui n'existe pas encore." },

{ id:"a5", n:"V", court:"Bagdad", t:"Bagdad : l'âge d'or arabe", per:"VIIIe – XIe siècle",
  lieux:[["Bagdad","Irak"],["Balkh","Afghanistan"],["Alep","Syrie"],["Ghazni","Afghanistan"],["Chiraz","Iran"]],
  hero:["astro/img/ah_iskandar2.webp","Le thème de naissance du prince Iskandar, petit-fils de Tamerlan, né le 25 avril 1384. Peint à Chiraz en 1411, c'est l'un des plus beaux horoscopes jamais réalisés : les planètes sont des personnages dans leurs signes. Wellcome Collection, CC BY 4.0."],
  lead:"Le 30 juillet 762, vers deux heures de l'après-midi, le calife al-Mansour fait poser la première brique de Bagdad. L'instant a été choisi par ses astrologues. Pendant trois siècles, la ville sera le lieu où tout le savoir du ciel est traduit, critiqué, augmenté.",
  blocs:[
   {h:"Tout traduire",
    p:["Les califes abbassides font venir des savants de tout l'empire. Le Persan <b>Nawbakht</b> et le Juif de Bassora <b>Masha'allah</b> calculent le thème de fondation de la ville. À la <b>Maison de la sagesse</b>, on met en arabe Ptolémée, Dorothée, les Perses et les Indiens. L'astrologie arabe hérite ainsi de toutes les traditions à la fois, et elle les met en ordre.",
       "Elle développe quatre branches que l'Europe reprendra telles quelles. Les <b>nativités</b> lisent le thème de naissance. Les <b>révolutions</b> étudient l'année qui vient, pour une personne ou pour le monde. Les <b>élections</b> choisissent le meilleur moment pour agir. Les <b>interrogations</b>, ou astrologie horaire, répondent à une question par le ciel de l'instant où elle est posée. Les astrologues multiplient aussi les <b>parts</b>, des points calculés dont la plus connue est la part de Fortune."]},
   {h:"Les maîtres",
    fig:["@h3","Abu Ma'shar, <i>Des grandes conjonctions</i>, édition latine imprimée à Augsbourg en 1489. Six siècles après sa mort, on l'imprime encore. Observatoire de Paris."],
    p:["<b>Abu Ma'shar</b>, né à Balkh en 787, était un spécialiste des traditions du Prophète, hostile aux philosophes. Le philosophe <b>al-Kindi</b>, raconte-t-on, le piqua au jeu en lui faisant étudier les mathématiques. À quarante-sept ans, il se tourne vers les étoiles et n'en revient plus. Sa <i>Grande Introduction</i> défend l'astrologie avec les arguments d'Aristote : les astres causent les changements d'ici-bas comme le Soleil cause les saisons. Son livre sur les grandes conjonctions applique à l'histoire entière la théorie perse de Jupiter et de Saturne.",
       "Au Xe siècle, <b>al-Qabisi</b>, à la cour d'Alep, écrit le manuel d'initiation que les étudiants d'Europe liront sous le nom d'Alcabitius. En 1029, à Ghazni, <b>al-Biruni</b>, esprit universel qui a mesuré le rayon de la Terre et décrit l'Inde, rédige pour une jeune femme nommée Rayhana un traité limpide, en questions et réponses. Il y expose tout, en glissant qu'il croit peu aux prédictions."]},
   {h:"Les instruments et les mots",
    fig:["astro/img/ah_astrolabe.webp","Un astrolabe d'Ispahan, fin du XVIIIe siècle. L'instrument donne l'heure, la hauteur des astres et l'Ascendant : dresser un thème sans lui prenait des heures. Art Institute of Chicago, CC0."],
    p:["Pour dresser un thème, il faut des tables et un instrument. Les savants de langue arabe perfectionnent l'<b>astrolabe</b>, qui permet de trouver l'heure et l'Ascendant en visant une étoile, et bâtissent des observatoires. Leur vocabulaire est resté dans nos langues : <i>zénith</i>, <i>nadir</i>, <i>azimut</i>, <i>almanach</i>, et les noms d'étoiles comme Aldébaran, Bételgeuse ou Véga.",
       "Tous n'approuvaient pas. Les philosophes <b>al-Farabi</b> et <b>Avicenne</b> écrivent contre l'astrologie des prédictions, qu'ils jugent indémontrable, et les théologiens la tiennent pour une atteinte à la toute-puissance de Dieu. Elle prospère pourtant dans toutes les cours, de Cordoue à Samarcande."]}
  ],
  gens:[
   {n:"Masha'allah", d:"vers 740 – 815", role:"Astrologue juif de Bassora",
    t:"L'un des astrologues de la fondation de Bagdad. Il écrit sur les interrogations, les éclipses et les conjonctions. Presque toute son œuvre n'est connue que par ses traductions latines, où il s'appelle Messahala."},
   {n:"Abu Ma'shar", d:"787 – 886", role:"« Albumasar », le prince des astrologues",
    t:"Né à Balkh, mort presque centenaire en Irak. Aucun auteur n'a été plus lu des astrologues latins. On racontait qu'il avait été fouetté sur ordre d'un calife pour une prédiction trop juste."},
   {n:"Al-Biruni", d:"973 – vers 1050", role:"Savant universel du Khwarezm",
    t:"Astronome, géographe, historien, il apprend le sanskrit pour comprendre l'Inde. Son manuel de 1029 est le plus clair que le Moyen Âge ait produit. C'est à lui qu'Arcanes emprunte les demi-orbes des planètes."}],
  qr:[
   ["Pourquoi choisir l'heure de fonder une ville ?","C'est une élection. Si le ciel de la naissance marque une personne, celui du commencement marque une entreprise. On choisissait de même l'heure d'un couronnement, d'un départ en campagne ou d'une saignée."],
   ["L'islam permettait-il l'astrologie ?","Les juristes l'ont le plus souvent réprouvée, en distinguant l'astronomie, utile pour les heures de prière et la direction de La Mecque, de la prédiction. Les princes, eux, ont entretenu des astrologues presque partout."],
   ["Qu'est-ce que l'astrologie horaire ?","Quelqu'un pose une question précise : retrouverai-je cet objet, ce navire arrivera-t-il ? L'astrologue dresse le thème de l'instant et y lit la réponse. William Lilly en fera sa spécialité huit siècles plus tard."]],
  mots:[["élection","Le choix du moment favorable pour commencer quelque chose."],["part","Un point calculé à partir de trois autres, comme la part de Fortune."],["astrolabe","L'instrument qui représente le ciel à plat et donne l'heure."]],
  globe:[["r_astro","La route de l'astrologie"],["soufisme","Le soufisme"]],
  suite:"Ces livres arabes vont revenir en Europe par l'Espagne, et y entrer par la grande porte : l'université." },

{ id:"a6", n:"VI", court:"Le Moyen Âge", t:"Le Moyen Âge latin : l'astrologie à l'université", per:"XIIe – XVe siècle",
  lieux:[["Tolède","Espagne"],["Bologne","Italie"],["Paris","France"],["Forlì","Italie"],["Oxford","Angleterre"]],
  hero:["@h4","L'homme zodiacal des <i>Très Riches Heures du duc de Berry</i>, par les frères de Limbourg, vers 1411-1416. Chaque signe gouverne une partie du corps, du Bélier à la tête aux Poissons aux pieds. Musée Condé, Chantilly."],
  lead:"Du XIIe au XVe siècle, l'astrologie n'est pas une croyance marginale : c'est une matière d'enseignement. On l'apprend avec l'astronomie, on s'en sert en médecine, et les théologiens discutent sérieusement de ce que les astres peuvent et ne peuvent pas.",
  blocs:[
   {h:"Le retour par Tolède",
    p:["Au XIIe siècle, à <b>Tolède</b> et en Sicile, des clercs venus de toute l'Europe traduisent de l'arabe en latin. Platon de Tivoli donne le <i>Tétrabible</i> en 1138, Jean de Séville la <i>Grande Introduction</i> d'Abu Ma'shar en 1133. Avec ces livres arrive Aristote, dont la physique semble les confirmer : tout ce qui change sous la Lune dépend des mouvements du ciel."]},
   {h:"Le médecin regarde la Lune",
    fig:["astro/img/ah_homme.webp","Un homme zodiacal dans un manuscrit médical : les douze signes désignent la partie du corps qu'il ne faut pas saigner quand la Lune s'y trouve. Wellcome Collection, CC BY 4.0."],
    p:["À <b>Bologne</b>, à Padoue, à Paris, l'astrologie est enseignée aux futurs médecins. La maladie est un déséquilibre des quatre humeurs, et les planètes agissent sur elles. Avant de saigner ou de purger, on consulte l'almanach : on ne touche pas un membre quand la Lune traverse le signe qui le gouverne. D'où ces images d'<b>homme zodiacal</b> que l'on trouve dans les livres d'heures comme dans les trousses des barbiers.",
       "En 1348, quand la peste noire ravage l'Europe, le roi de France demande un avis à la faculté de médecine de Paris. La réponse est officielle : la cause première est la conjonction de Saturne, Jupiter et Mars dans le Verseau, le 20 mars 1345, qui a corrompu l'air."]},
   {h:"Les astres inclinent",
    p:["Reste la question de la liberté. <b>Thomas d'Aquin</b> la règle par une distinction qui servira pendant quatre siècles. Les astres agissent sur les corps, donc sur les humeurs et les passions. Mais la volonté est libre : celui qui gouverne ses passions échappe à leur influence. La plupart des hommes ne le font pas, c'est pourquoi les astrologues voient souvent juste pour les foules. On résumera par un adage : les astres inclinent, ils ne contraignent pas.",
       "La limite est surveillée. En 1277, l'évêque de Paris condamne ceux qui enseignent que tout arrive par nécessité céleste. En 1327, <b>Cecco d'Ascoli</b>, professeur à Bologne, est brûlé à Florence pour avoir, entre autres, soumis aux astres la naissance du Christ."]},
   {h:"Les enfants des planètes",
    fig:["astro/img/ah_planetes.webp","Les sept planètes personnifiées en ronde, dans un manuscrit allemand. Chacune a ses « enfants » : les métiers, les tempéraments et les âges de la vie qu'elle gouverne. Wellcome Collection, CC BY 4.0."],
    p:["L'astrologie donne au Moyen Âge une grande part de ses images. Sur les murs des palais communaux, dans les calendriers, on peint les <b>enfants des planètes</b> : sous Saturne, les laboureurs, les mendiants et les prisonniers ; sous Vénus, les amants et les musiciens ; sous Mercure, les marchands, les peintres et les horlogers. Le vocabulaire en garde la trace. Nous disons encore d'une personne qu'elle est joviale, martiale, lunatique, saturnienne, ou qu'elle est née sous une bonne étoile. Un <i>désastre</i> est, mot à mot, un mauvais astre."]}
  ],
  gens:[
   {n:"Guido Bonatti", d:"vers 1210 – vers 1296", role:"L'astrologue le plus célèbre du Moyen Âge",
    t:"Né à Forlì, il sert plusieurs seigneurs de guerre, dont Guido da Montefeltro. Du haut d'un clocher, dit-on, il donnait par trois coups de cloche le signal de s'armer, de monter en selle et de partir. Son <i>Livre d'astronomie</i> est une somme de la tradition arabe. Dante le place en enfer, parmi les devins, la tête tournée vers l'arrière."},
   {n:"Thomas d'Aquin", d:"1225 – 1274", role:"Théologien dominicain",
    t:"Il n'a jamais dressé un thème. Mais sa solution, qui accorde aux astres le corps et réserve l'âme, a permis à l'astrologie de rester enseignable dans la chrétienté."}],
  qr:[
   ["L'astrologie était-elle une science au Moyen Âge ?","Oui, au sens de l'époque. On ne distinguait pas deux métiers : l'<i>astronomia</i> comprenait le calcul des positions et leur interprétation. Les mêmes hommes faisaient les deux."],
   ["Tout le monde y croyait-il ?","Non. Nicole Oresme, évêque et mathématicien du XIVe siècle, écrit un traité entier pour détourner le roi Charles V de ses astrologues : les mouvements célestes, dit-il, ne se répètent jamais exactement, on ne peut donc rien prévoir."],
   ["Pourquoi la conjonction de 1345 pour expliquer la peste ?","Parce que, dans la physique d'Aristote, les grands changements d'ici-bas ont une cause céleste. Les médecins ajoutaient des causes proches, comme l'air corrompu. L'explication n'était pas absurde pour l'époque : elle était la meilleure disponible."]],
  mots:[["humeurs","Sang, flegme, bile jaune et bile noire : les quatre liquides dont l'équilibre fait la santé."],["mélothésie","La répartition du corps entre les signes du zodiaque."],["judiciaire","Se dit de l'astrologie qui porte des jugements sur les destinées."]],
  suite:"L'imprimerie va mettre des éphémérides dans toutes les mains, et les astronomes les plus célèbres de l'histoire vont dresser des horoscopes." },

{ id:"a7", n:"VII", court:"La Renaissance", t:"La Renaissance : princes, prophètes et astronomes", per:"1450 – 1630",
  lieux:[["Nuremberg","Allemagne"],["Florence","Italie"],["Wittenberg","Allemagne"],["Salon-de-Provence","France"],["Prague","Bohême"]],
  hero:["astro/img/ah_durer.webp","La carte du ciel boréal d'Albrecht Dürer, 1515, première carte céleste imprimée en Europe. Aux angles, quatre autorités : Aratos le Grec, Ptolémée l'Égyptien, Manilius le Romain et al-Soufi l'Arabe. Art Institute of Chicago, CC0."],
  lead:"Jamais l'astrologie n'a été aussi présente qu'entre 1450 et 1630. Chaque prince a son astrologue, chaque ville son almanach. Et les hommes qui vont changer l'image du monde, Copernic, Tycho Brahe, Kepler, Galilée, vivent tous au milieu d'elle.",
  blocs:[
   {h:"L'imprimerie et la grande peur de 1524",
    fig:["astro/img/ah_regio.webp","Ptolémée et Regiomontanus sous la sphère armillaire, frontispice de l'<i>Épitomé de l'Almageste</i>, Venise, 1496. Wellcome Collection, domaine public."],
    p:["En 1474, à <b>Nuremberg</b>, l'astronome <b>Regiomontanus</b> imprime sur sa propre presse les premières éphémérides : la position des planètes jour par jour pour trente ans. Christophe Colomb en emporte un exemplaire ; en 1504, à la Jamaïque, il s'en sert pour annoncer une éclipse de Lune aux habitants et obtenir des vivres. Désormais, n'importe qui peut dresser un thème sans savoir calculer.",
       "Les éphémérides de Stöffler, parues en 1499, signalent pour février 1524 une vingtaine de conjonctions dans le signe d'eau des Poissons. On en conclut à un nouveau Déluge. Plus de cinquante auteurs publient plus de cent trente brochures pour ou contre ; des familles s'installent sur les hauteurs, un magistrat de Toulouse fait construire une arche. Le mois de février fut plutôt sec."]},
   {h:"Pour et contre",
    p:["À Florence, <b>Marsile Ficin</b> soigne les mélancoliques en les accordant aux planètes favorables, par la musique et les parfums. Son ami <b>Pic de la Mirandole</b> écrit au contraire, peu avant de mourir en 1494, douze livres <i>Contre l'astrologie divinatrice</i> : le ciel n'agit que par la lumière et la chaleur, et l'homme, libre, ne saurait dépendre des étoiles. C'est la critique la plus complète jamais écrite ; tous les adversaires y puiseront.",
       "La Réforme se divise. Luther se moque des astrologues ; son bras droit <b>Melanchthon</b> enseigne l'astrologie à Wittenberg et corrige d'un an la date de naissance de Luther pour lui trouver un meilleur thème. À Rome, les papes consultent, puis interdisent : une bulle de 1586 condamne l'astrologie judiciaire, une autre en 1631, après que des astrologues eurent annoncé un peu trop fort la mort d'Urbain VIII."]},
   {h:"Nostradamus",
    p:["<b>Michel de Nostredame</b>, médecin provençal, publie à partir de 1550 des almanachs annuels, puis en 1555 ses <i>Prophéties</i> : des quatrains obscurs, rangés par centaines. Catherine de Médicis le fait venir à la cour. Il faut le dire nettement : Nostradamus est un piètre astrologue. Les thèmes qu'il a dressés sont pleins de fautes de calcul, et ses confrères le lui reprochaient. Ses quatrains ne doivent presque rien aux astres et beaucoup aux chroniques anciennes. Leur flou a fait leur fortune : on y trouve après coup ce qu'on veut."]},
   {h:"Tycho, Kepler, Galilée",
    fig:["astro/img/ah_kepler.webp","Johannes Kepler, gravure. Il a laissé plus de huit cents thèmes dressés de sa main. Wellcome Collection, domaine public."],
    p:["Le Danois <b>Tycho Brahe</b>, le plus grand observateur avant la lunette, dresse les thèmes des enfants du roi et publie des pronostics. Mais il montre aussi, en 1572 puis en 1577, qu'une étoile nouvelle et une comète se trouvent bien au-delà de la Lune : le ciel n'est donc pas immuable, contrairement à ce qu'enseignait Aristote.",
       "Son assistant puis successeur à Prague, <b>Johannes Kepler</b>, vit en partie de ses almanachs. Il découvre que les planètes décrivent des ellipses, et il passe sa vie à réformer l'astrologie. Il rejette les signes, les maisons et presque toutes les règles, qu'il tient pour des superstitions. Il garde les <b>aspects</b>, parce qu'il y voit une géométrie à laquelle l'âme de la Terre et celle de l'homme répondent comme à un accord musical, et il en invente de nouveaux. À ceux qui veulent tout jeter, il répond en 1610 qu'il ne faut pas jeter l'enfant avec l'eau du bain. Il appelle l'astrologie la fille un peu folle de l'astronomie, mais ajoute que c'est la fille qui nourrit la mère. En 1608, il dresse pour un inconnu un thème resté fameux : celui du futur général Wallenstein.",
       "<b>Galilée</b> lui-même, professeur à Padoue, enseigne l'astrologie aux étudiants en médecine, dresse les thèmes de ses filles et celui du grand-duc de Toscane. Aucun de ces hommes ne voit là une contradiction. Elle viendra de leurs découvertes, pas de leurs intentions."]}
  ],
  gens:[
   {n:"Regiomontanus", d:"1436 – 1476", role:"Astronome et imprimeur",
    t:"Johannes Müller, de Königsberg en Franconie, d'où son surnom latin. Il donne son nom à un système de maisons que suivront Lilly et Morin. Appelé à Rome pour réformer le calendrier, il y meurt à quarante ans."},
   {n:"Nostradamus", d:"1503 – 1566", img:"astro/img/ah_nostra.webp", cap:"Michel Nostradamus, gravure. Wellcome Collection.", role:"Médecin, auteur d'almanachs et de prophéties",
    t:"Né à Saint-Rémy-de-Provence, installé à Salon. Il a soigné des pestiférés et publié un traité des confitures. Sa célébrité tient à un quatrain où l'on a lu, après coup, la mort du roi Henri II dans un tournoi en 1559."},
   {n:"Tycho Brahe", d:"1546 – 1601", img:"astro/img/ah_tycho.webp", cap:"Tycho Brahe, gravure d'après un portrait de 1586. Wellcome Collection.", role:"Astronome danois",
    t:"Seigneur de l'île de Hven, où il bâtit un observatoire-château. Il y forme des assistants, fabrique ses instruments et mesure le ciel avec une précision jamais atteinte. Il meurt à Prague, astronome de l'empereur Rodolphe II."},
   {n:"Johannes Kepler", d:"1571 – 1630", img:"astro/img/ah_kepler.webp", cap:"Johannes Kepler, gravure. Wellcome Collection.", role:"Astronome, mathématicien de l'empereur",
    t:"Né dans le Wurtemberg, de santé fragile, il défend sa mère accusée de sorcellerie. Ses trois lois fondent l'astronomie moderne. Les aspects mineurs qu'il a proposés, quintile ou sesqui-carré, sont encore utilisés."},
   {n:"Galilée", d:"1564 – 1642", img:"astro/img/ah_galilee.webp", cap:"Galilée, gravure. Wellcome Collection.", role:"Physicien et astronome",
    t:"En 1604, un ancien secrétaire le dénonce à l'Inquisition de Padoue pour avoir prédit des destinées comme si elles étaient inévitables. L'affaire est classée. En 1610, il dédie aux Médicis les satellites de Jupiter, en rappelant que Jupiter dominait le thème du grand-duc."}],
  qr:[
   ["Comment de grands savants ont-ils pu y croire ?","La question suppose que la frontière était déjà tracée. Elle ne l'était pas. L'idée que les astres agissent sur la Terre était une hypothèse de physique raisonnable ; ce qu'on discutait, c'était jusqu'où et par quels moyens."],
   ["Nostradamus a-t-il prédit quelque chose ?","Rien de daté ni de précis qui se soit vérifié avant l'événement. Tous les « succès » sont des lectures faites après coup, souvent en retouchant la traduction."],
   ["Copernic a-t-il ruiné l'astrologie en 1543 ?","Pas sur le moment. Les astrologues ont adopté ses tables, plus exactes, sans changer leur pratique : vu de la Terre, le ciel reste le même. C'est la physique qui a tout changé, un siècle plus tard."]],
  mots:[["éphémérides","Des tables qui donnent la position des planètes jour par jour."],["pronostic","La brochure annuelle où un astrologue annonce le temps, les récoltes et les événements."],["aspect mineur","Un angle ajouté par Kepler aux cinq aspects des Anciens."]],
  globe:[["ficin","La Renaissance hermétique"],["dee","John Dee"]],
  suite:"Le siècle suivant donne à l'astrologie ses deux plus grands traités, puis lui ferme la porte des sciences." },

{ id:"a8", n:"VIII", court:"Le XVIIe siècle", t:"Le XVIIe siècle : l'apogée et la rupture", per:"1630 – 1720",
  lieux:[["Londres","Angleterre"],["Paris","France"],["La Haye","Pays-Bas"],["Padoue","Italie"]],
  hero:["@h7","William Lilly en 1660, gravure. Il tient un thème où l'on lit « non cogunt » : les astres ne contraignent pas. Wellcome Collection, CC BY 4.0."],
  lead:"En cinquante ans, l'astrologie passe du sommet au discrédit. Elle n'a pas été réfutée par une expérience décisive. Elle a perdu le monde qui lui donnait un sens, et les gens instruits ont cessé de la prendre au sérieux.",
  blocs:[
   {h:"Lilly : l'astrologue de la guerre civile",
    p:["Fils de paysan, <b>William Lilly</b> monte à Londres comme domestique, épouse la veuve de son maître et apprend l'astrologie à trente ans. Pendant la guerre civile anglaise, ses almanachs, favorables au Parlement, se vendent à trente mille exemplaires ; les deux camps le lisent. Dans son cabinet du Strand, il reçoit près de deux mille clients par an, servantes et grandes dames : un objet perdu, un mari en mer, un procès.",
       "En 1647, il publie <b>Christian Astrology</b>, huit cents pages en anglais et non en latin : le premier manuel que tout le monde peut lire, et le grand traité d'astrologie horaire. En 1651, il fait paraître des gravures énigmatiques montrant une ville en flammes et des fossoyeurs. Après la peste de 1665 et le grand incendie de Londres en 1666, une commission du Parlement le convoque pour savoir s'il était au courant. Il répond que non, et on le laisse aller."]},
   {h:"Morin : le dernier système",
    fig:["@h5","Jean-Baptiste Morin de Villefranche, gravure d'Étienne Desrochers. Son grand livre a paru cinq ans après sa mort."],
    p:["En France, <b>Jean-Baptiste Morin</b>, médecin né à Villefranche-sur-Saône, occupe la chaire de mathématiques du Collège royal. Il a la confiance de Richelieu puis de Mazarin, et l'on dit qu'il se tenait près de la chambre de la reine, en 1638, pour noter l'instant où naissait le futur Louis XIV. Adversaire de Copernic et de Galilée, querelleur, il consacre trente ans à l'<b>Astrologia Gallica</b>, vingt-six livres en latin, imprimés à La Haye en 1661.",
       "C'est la tentative la plus rigoureuse de refonder l'astrologie par la raison. Morin élimine ce qu'il juge arbitraire et bâtit tout sur une idée : une planète agit selon son <b>état céleste</b> et selon la maison qu'elle occupe et celles qu'elle gouverne. La tradition française s'en réclame encore. Mais le livre arrive trop tard : presque personne ne le lit."]},
   {h:"Pourquoi elle sort des sciences",
    fig:["astro/img/ah_academie.webp","L'Académie des sciences et des beaux-arts, gravure du XVIIe siècle. On y voit tous les savoirs à l'œuvre ; l'astrologie n'y a plus sa place. Wellcome Collection, domaine public."],
    p:["Le cosmos de Ptolémée était un emboîtement de sphères autour de la Terre, où le haut gouverne le bas. Avec Copernic, Kepler et Galilée, la Terre devient une planète parmi d'autres. Avec <b>Newton</b>, en 1687, une seule force, la gravitation, explique la chute d'une pomme et la course de la Lune. Elle se calcule, et elle ne dit rien des caractères. Les quatre éléments, les qualités, les sympathies, tout le langage dans lequel l'astrologie se justifiait cesse d'avoir cours.",
       "Les institutions suivent. L'Académie des sciences, fondée par Colbert en 1666, n'admet pas d'astrologues. En 1682, l'édit de Louis XIV qui clôt l'affaire des Poisons range les « devins » parmi les imposteurs. Les universités cessent de l'enseigner l'une après l'autre.",
       "Le ridicule achève le travail. En 1682, <b>Pierre Bayle</b> démontre sur des centaines de pages que les comètes n'annoncent rien. En 1708, l'écrivain Jonathan Swift, sous un faux nom, prédit la mort de l'astrologue Partridge pour le 29 mars, puis publie le récit de ses derniers instants. Partridge passe des mois à jurer qu'il est vivant ; tout Londres en rit."]}
  ],
  gens:[
   {n:"William Lilly", d:"1602 – 1681", img:"astro/img/ah_lilly.webp", cap:"William Lilly, eau-forte de Wenceslas Hollar. Wellcome Collection.", role:"Astrologue anglais, maître de l'astrologie horaire",
    t:"Né à Diseworth, dans le Leicestershire. Ses carnets de consultation, conservés à Oxford, montrent sa méthode jour après jour. Retiré à la campagne, il finit médecin de village. Les astrologues traditionnels d'aujourd'hui le relisent ligne à ligne."},
   {n:"Jean-Baptiste Morin de Villefranche", d:"1583 – 1656", role:"Médecin, mathématicien, astrologue de cour",
    t:"Docteur à Avignon, il voyage dans les mines de Hongrie avant de se fixer à Paris. Il se brouille avec Descartes et Gassendi. La reine de Pologne, dont il avait prédit le mariage, paie l'impression de son œuvre."},
   {n:"Placidus de Titis", d:"1603 – 1668", role:"Moine olivétain, professeur à Pavie",
    t:"Il propose de diviser les maisons selon le temps que met chaque degré à monter de l'horizon au méridien. Mis à l'Index, son système sera repris par les Anglais et deviendra, grâce aux tables imprimées, le plus répandu au XXe siècle."}],
  qr:[
   ["Qui a « prouvé » que l'astrologie était fausse ?","Personne en particulier. Elle n'a pas été abattue par un argument nouveau : ceux de Cicéron et de Pic suffisaient. Elle est tombée avec la physique d'Aristote, qui la soutenait, et parce que les savants avaient désormais mieux à faire."],
   ["Newton était-il astrologue ?","Non. On lui prête une réplique à l'astronome Halley, « moi, monsieur, j'ai étudié la question, pas vous », mais elle concernait la théologie. Sa bibliothèque ne contenait presque rien sur l'astrologie. Il s'est en revanche beaucoup occupé d'alchimie."],
   ["Que devient-elle après 1700 ?","Elle ne disparaît pas, elle change de public. Elle quitte les cours et les universités pour les almanachs que l'on vend sur les marchés."]],
  mots:[["astrologie horaire","Répondre à une question par le thème de l'instant où elle est posée."],["domification","La manière de diviser le ciel en douze maisons."],["état céleste","Chez Morin, la force d'une planète selon son signe et ses aspects."]],
  suite:"Pendant un siècle et demi, l'astrologie vit dans les almanachs. Puis l'Angleterre la réveille." },

{ id:"a9", n:"IX", court:"Le renouveau", t:"Des almanachs au signe solaire", per:"1700 – 1940",
  lieux:[["Londres","Angleterre"],["Paris","France"],["Hambourg et Munich","Allemagne"]],
  hero:["astro/img/ah_signes.webp","Trois constellations coloriées, gravure du XIXe siècle. Au moment où l'astrologie quitte les sciences, ses images entrent dans les salons et les livres d'étrennes. Wellcome Collection, domaine public."],
  lead:"L'astrologie d'aujourd'hui, celle qui te demande « tu es de quel signe ? », a moins de cent cinquante ans. Elle est née en Angleterre, de la rencontre d'un vieux savoir tombé dans les almanachs et d'un mouvement spirituel nouveau, puis elle a été simplifiée par la presse.",
  blocs:[
   {h:"Le temps des almanachs",
    fig:["astro/img/ah_almanach.webp","Un almanach d'Utrecht pour 1655 : le calendrier, les lunaisons, les jours favorables pour saigner, semer et couper le bois. Wellcome Collection, domaine public."],
    p:["Au XVIIIe siècle, l'astrologie savante n'a plus d'auteurs, mais l'almanach reste, avec la Bible, le livre le plus vendu d'Europe. En Angleterre, celui de Francis Moore, fondé en 1697, paraît toujours. On y cherche les phases de la Lune, la météo de l'année, les jours bons pour semer.",
       "Dans les années 1820, à Londres, deux hommes relancent le genre sous des noms d'anges. <b>Raphael</b> publie un almanach prophétique et des éphémérides annuelles qui existent encore. <b>Zadkiel</b>, ancien officier de marine, annonce en 1861 une mauvaise année pour le prince consort, qui meurt en décembre ; attaqué dans la presse, il fait un procès en diffamation et gagne vingt shillings.",
       "Le ciel, lui, s'est agrandi. <b>Uranus</b> est découverte en 1781, <b>Neptune</b> en 1846, <b>Pluton</b> en 1930. Les astrologues leur attribuent des significations d'après l'époque de leur découverte et le nom que les astronomes leur ont donné : la révolution et l'électricité pour Uranus, le rêve et la dissolution pour Neptune, les profondeurs et l'atome pour Pluton. Les traditionalistes d'aujourd'hui leur reprochent justement ce procédé."]},
   {h:"Alan Leo : du destin au caractère",
    fig:["@h6","Un thème dressé au début du XXe siècle, publié dans <i>The Life and Work of Alan Leo</i>, 1919. La roue ronde, qui remplace le carré des Anciens, se répand à cette époque."],
    p:["En 1875 naît à New York la <b>Société théosophique</b>, qui mêle les religions de l'Inde, l'occultisme et l'idée d'une évolution des âmes de vie en vie. Un voyageur de commerce londonien, William Frederick Allan, y adhère en 1890 et prend le nom d'<b>Alan Leo</b>, d'après son signe. Pour lui, le thème de naissance n'est plus une liste d'événements : c'est le portrait d'une âme et le programme de ses progrès. Le Soleil, jusque-là une planète parmi d'autres, devient le centre du thème.",
       "Leo a aussi le sens des affaires. Il vend par correspondance des horoscopes à un shilling, assemblés à partir de feuillets imprimés d'avance, un par position. Le succès est immense. La justice l'attaque deux fois pour avoir « dit la bonne aventure » ; condamné en 1917 à une amende, il décide de bannir toute prédiction et de ne plus parler que de <b>tendances</b>. L'astrologie psychologique est née d'un procès."]},
   {h:"Le signe solaire entre dans le journal",
    fig:["@h8","La gravure dite de Flammarion, parue dans <i>L'Atmosphère</i> en 1888 : un voyageur passe la tête à travers la voûte du ciel. Souvent prise pour une image médiévale, elle date du XIXe siècle."],
    p:["Le 24 août 1930, trois jours après la naissance de la princesse Margaret, le <i>Sunday Express</i> de Londres publie son thème, commenté par l'astrologue <b>R. H. Naylor</b>. Les lecteurs en redemandent. Quelques semaines plus tard, Naylor semble avoir annoncé la catastrophe d'un dirigeable : on lui donne une rubrique hebdomadaire.",
       "Comment parler à des millions de lecteurs dont on ignore l'heure de naissance ? En ne retenant que le signe où se trouvait le Soleil, que chacun connaît par sa date d'anniversaire. À la fin des années 1930, la formule des <b>douze paragraphes</b> est en place, et elle n'a plus bougé. Elle a rendu l'astrologie universelle, et elle l'a réduite à un douzième d'elle-même.",
       "Sur le continent, le renouveau prend d'autres formes. En France, le polytechnicien <b>Paul Choisnard</b> cherche à la vérifier par les statistiques. En Allemagne, où elle connaît dans les années 1920 une vogue extraordinaire, elle est d'abord courtisée par les nazis, puis interdite et ses praticiens arrêtés en juin 1941, après la fuite de Rudolf Hess, que l'on disait conseillé par des astrologues."]}
  ],
  gens:[
   {n:"Alan Leo", d:"1860 – 1917", role:"Le père de l'astrologie moderne",
    t:"Né à Londres dans une famille pauvre. Sa revue <i>Modern Astrology</i> et ses manuels, traduits dans toute l'Europe, ont formé deux générations. Presque tout ce qu'on dit aujourd'hui des signes vient de lui ou de ses élèves."},
   {n:"Paul Choisnard", d:"1867 – 1930", role:"Polytechnicien, pionnier de l'astrologie statistique",
    t:"Officier d'artillerie, il compare des centaines de thèmes pour chercher des fréquences anormales. Ses méthodes étaient fragiles, mais il a ouvert la voie que Michel Gauquelin reprendra avec rigueur."},
   {n:"R. H. Naylor", d:"1889 – 1952", role:"Inventeur de l'horoscope de presse",
    t:"Assistant d'un astrologue mondain, il remplace son patron au pied levé pour l'article sur la princesse. En mai 1939, il assure à ses lecteurs que l'Europe ne sera pas le foyer d'un conflit."}],
  qr:[
   ["Depuis quand demande-t-on « tu es de quel signe » ?","Depuis les années 1930. Auparavant, un astrologue aurait regardé d'abord l'Ascendant et la Lune. Le signe solaire s'est imposé parce qu'il suffit d'une date pour le connaître."],
   ["Pourquoi les planètes récentes ont-elles un sens ?","Par analogie. On a observé ce qui se passait dans le monde quand elles ont été découvertes, et l'on a brodé sur le nom mythologique choisi par les astronomes. Aucune observation ancienne ne les fonde."],
   ["L'horoscope du journal est-il de l'astrologie ?","C'en est une version extrêmement simplifiée, que la plupart des astrologues eux-mêmes ne défendent pas. Un thème complet tient compte de dix astres, de douze maisons et de l'heure de naissance."]],
  mots:[["signe solaire","Le signe où se trouvait le Soleil à la naissance."],["Théosophie","Le mouvement spirituel fondé en 1875 par Helena Blavatsky."],["planètes transsaturniennes","Uranus, Neptune et Pluton, invisibles à l'œil nu."]],
  globe:[["theosophie","La Théosophie"]],
  suite:"Il reste à raconter le dernier siècle : la rencontre avec la psychologie, le retour aux textes anciens, et l'épreuve des statistiques." },

{ id:"a10", n:"X", court:"Aujourd'hui et la science", t:"Psychologie, retour aux sources, et ce que dit la science", per:"1930 – aujourd'hui",
  lieux:[["Zurich","Suisse"],["Paris","France"],["Londres","Angleterre"],["Californie","États-Unis"]],
  lead:"Au XXe siècle, l'astrologie devient un langage pour parler de soi. Puis une partie des astrologues, lassée de ce flou, retourne lire les Grecs et les Arabes. Dans le même temps, des chercheurs la soumettent pour la première fois à des tests contrôlés. Les trois histoires sont à connaître.",
  blocs:[
   {h:"L'astrologie psychologique",
    p:["Le psychiatre suisse <b>Carl Gustav Jung</b> écrit à Freud, en 1911, que ses soirées sont prises par l'astrologie. Il n'y cherche pas des causes. Les dieux planétaires sont pour lui des <b>archétypes</b>, des figures de l'inconscient collectif, et le lien entre un ciel et une vie relève de ce qu'il appelle la <b>synchronicité</b> : une coïncidence qui fait sens sans qu'il y ait de cause. Il tente même une étude sur les thèmes de quatre cent quatre-vingt-trois couples mariés, et reconnaît que le résultat ne prouve rien.",
       "<b>Dane Rudhyar</b>, compositeur né à Paris et installé en Californie, donne en 1936 sa doctrine à ce courant : le thème est une graine, un potentiel à accomplir, et non un verdict. Après 1960, cette astrologie « humaniste » rencontre la contre-culture. On chante l'ère du Verseau, et en 1968 le livre de <b>Linda Goodman</b> sur les signes solaires devient le premier ouvrage d'astrologie à figurer parmi les meilleures ventes américaines.",
       "En France, <b>André Barbault</b> relie l'astrologie à la psychanalyse et étudie les cycles planétaires dans l'histoire, tandis que <b>Jean-Pierre Nicola</b> cherche à la refonder sur les rythmes astronomiques réels. À Londres, l'analyste <b>Liz Greene</b> renouvelle la lecture de Saturne et fonde en 1983 une école d'astrologie psychologique. Dans les mêmes années, l'ordinateur supprime le calcul : un thème qui demandait une heure s'obtient en une seconde."]},
   {h:"Le retour aux sources",
    p:["Vers 1980, des astrologues s'avisent qu'ils n'ont jamais lu leurs classiques. La plupart des textes grecs, arabes et latins n'ont pas été traduits, ou l'ont été par des philologues qui ne pratiquaient pas. En 1993, aux États-Unis, <b>Robert Schmidt</b>, <b>Robert Hand</b> et Robert Zoller lancent le <b>Projet Hindsight</b> pour les traduire. On redécouvre des outils oubliés depuis trois siècles : la distinction entre thèmes de jour et de nuit, les signes entiers pris pour maisons, les dignités, les profections annuelles, les parts.",
       "Cette astrologie <b>traditionnelle</b> est plus technique et plus concrète. Elle décrit des circonstances plutôt que des états d'âme. En France, <b>Denis Labouré</b> en est l'un des principaux artisans, par ses commentaires de Ptolémée, des Arabes et de Morin. Le livre de <b>Chris Brennan</b> sur l'astrologie hellénistique, en 2017, l'a fait connaître à un large public. Arcanes te propose les deux lectures, moderne et tradition, parce qu'elles ne posent pas les mêmes questions à un thème."]},
   {h:"L'épreuve des faits",
    p:["En 1955, le psychologue français <b>Michel Gauquelin</b>, qui voulait réfuter l'astrologie, trouve un résultat inattendu : sur plus de deux mille champions sportifs, Mars se trouve un peu plus souvent que prévu juste après son lever ou sa culmination. Cet <b>effet Mars</b> a occupé les statisticiens pendant quarante ans. Les vérifications indépendantes ne l'ont pas retrouvé de façon convaincante, et l'on soupçonne des biais dans le choix des champions. Gauquelin lui-même n'a rien trouvé du côté des signes, des aspects ni des prédictions d'astrologues.",
       "En 1985, la revue <i>Nature</i> publie l'expérience du physicien <b>Shawn Carlson</b>, mise au point avec des astrologues réputés. Ceux-ci reçoivent un thème et trois profils psychologiques, dont celui de la personne. Ils devaient, de leur propre aveu, trouver le bon une fois sur deux. Ils le trouvent une fois sur trois : le hasard. En 2003, Geoffrey Dean et Ivan Kelly étudient plus de deux mille personnes nées à Londres à quelques minutes d'intervalle. Ces « jumeaux de ciel » ne se ressemblent pas plus que des inconnus.",
       "Pourquoi, alors, un thème semble-t-il si juste ? En 1949, le psychologue <b>Bertram Forer</b> remet à ses étudiants un portrait « personnalisé » et leur demande de le noter. Ils lui donnent en moyenne plus de quatre sur cinq. Tous avaient reçu le même texte, recopié d'un livre d'horoscopes. Nous nous reconnaissons dans une description assez large et assez flatteuse, et nous retenons ce qui tombe juste. C'est l'<b>effet Barnum</b>."]},
   {h:"Ce qu'il en reste",
    p:["Selon les sondages, entre un quart et quatre personnes sur dix, en Europe et en Amérique du Nord, disent accorder du crédit à l'astrologie, et bien davantage en Inde. Elle n'a jamais eu autant de lecteurs qu'à l'âge des applications.",
       "Tu peux en tirer deux conclusions, qui ne s'excluent pas. La première : rien n'indique que la position des planètes à ta naissance détermine ton caractère ou ton avenir. La seconde : pendant vingt-cinq siècles, des gens très intelligents ont rangé dans ce système tout ce qu'ils savaient de l'âme humaine, des tempéraments, des âges de la vie et des façons d'aimer. Il a nourri l'astronomie, la médecine, la peinture et la langue. C'est ainsi qu'Arcanes le présente : un vocabulaire d'une grande finesse pour réfléchir à soi, pas une science qui prédit."]}
  ],
  gens:[
   {n:"Carl Gustav Jung", d:"1875 – 1961", role:"Psychiatre, fondateur de la psychologie analytique",
    t:"Il faisait dresser le thème de certains patients pour y chercher, disait-il, un éclairage sur des cas difficiles. Ses notions d'archétype et de synchronicité ont donné aux astrologues du XXe siècle leur philosophie."},
   {n:"Dane Rudhyar", d:"1895 – 1985", role:"Compositeur et astrologue",
    t:"Né Daniel Chennevière à Paris, parti à vingt et un ans pour les États-Unis. <i>The Astrology of Personality</i> (1936) est le livre fondateur de l'astrologie humaniste. Il a écrit que l'astrologie n'a pas à être « vraie », mais utile à la croissance d'une personne."},
   {n:"André Barbault", d:"1921 – 2019", role:"Le grand nom de l'astrologie française",
    t:"Autodidacte bourguignon. <i>De la psychanalyse à l'astrologie</i> (1961) rapproche les deux disciplines. Il invente un indice cyclique pour suivre les crises mondiales, et lance en 1968 le premier service d'horoscopes par ordinateur."},
   {n:"Michel Gauquelin", d:"1928 – 1991", role:"Psychologue et statisticien",
    t:"Avec sa femme Françoise, il a rassemblé dans les mairies des dizaines de milliers d'heures de naissance. Critique sévère des astrologues, il est aussi celui qui a pris leur hypothèse le plus au sérieux."},
   {n:"Robert Hand", d:"né en 1942", role:"Astrologue et historien américain",
    t:"Auteur de classiques modernes sur les transits, puis l'un des moteurs du retour à la tradition. Son petit livre <i>Night and Day</i> (1995) a remis au centre la différence entre thèmes diurnes et nocturnes."},
   {n:"Denis Labouré", role:"Astrologue français, passeur de la tradition",
    t:"Par ses livres et son enseignement, il a remis en usage dans le monde francophone les outils de Ptolémée, des Arabes et de Morin de Villefranche : dignités, maîtrises, révolutions solaires, directions. C'est la lecture qu'Arcanes suit dans son mode « tradition »."}],
  qr:[
   ["Des scientifiques ont-ils pris position ?","En 1975, cent quatre-vingt-six savants, dont dix-huit prix Nobel, ont signé un texte intitulé « Objections à l'astrologie ». L'astronome Carl Sagan a refusé de le signer, non qu'il y crût, mais parce qu'il trouvait le ton autoritaire : il fallait, selon lui, examiner et non décréter."],
   ["La Lune agit bien sur les marées. Pourquoi pas sur nous ?","Les marées viennent de la différence d'attraction entre les deux côtés de la Terre, qui est immense. À l'échelle d'un corps humain, cette différence est insignifiante : la sage-femme, à la naissance, attire davantage le nouveau-né que la planète Mars."],
   ["Puis-je m'en servir sans y croire ?","Oui, et c'est le parti d'Arcanes. Un thème peut se lire comme on lit un mythe ou un tirage de tarot : il propose des images, tu regardes lesquelles te parlent et pourquoi. Ce qui compte alors, c'est la question que tu te poses."],
   ["Moderne ou traditionnelle : laquelle choisir ?","Elles ne servent pas à la même chose. La lecture moderne parle de motivations et de vie intérieure. La lecture traditionnelle parle de situations, de forces et de faiblesses, avec des règles plus strictes. Essaie les deux sur ton thème, dans l'onglet Thème."]],
  mots:[["archétype","Chez Jung, une figure universelle de l'inconscient."],["synchronicité","Une coïncidence qui a du sens sans lien de cause."],["effet Barnum","Notre tendance à nous reconnaître dans un portrait vague."],["astrologie traditionnelle","Celle qui applique les règles d'avant 1700."]],
  suite:"L'histoire est faite. Le reste se passe dans ton propre ciel." }
];
